  it('fails on the patched build', () => {
    // Explicit !!int on an unsigned octal must resolve like implicit resolution does.
    assert.strictEqual(load('!!int 0o7'), 7);
  });
});
"}, "note": "The explicit integer pattern in intCoreTag lost the optional sign before `0o`, so `!!int 0o7` (and other unsigned octal forms under an explicit tag) now fails to resolve, whereas implicit resolution still accepts `0o7`."}
